defmodule ProCoder.Planner.DAG.Requirements.Dependencies do
  @moduledoc """
  Authoritative dependency manifest for the ProCoder DAG Orchestrator.
  Ensures structural integrity and environment compliance for graph-based planning.
  """

  require Logger

  @type version_spec :: String.t()
  @type dep_map :: %{atom() => version_spec()}
  @type spec_map :: %{
    dependencies: dep_map(),
    compatibility_matrix: map(),
    checksum: String.t()
  }

  @doc """
  Returns the pre-computed, immutable dependency specification for the DAG orchestrator.
  """
  @spec get_spec() :: spec_map()
  def get_spec do
    %{
      dependencies: %{
        libgraph: "~> 0.16.0",
        jason: "~> 1.4.0"
      },
      compatibility_matrix: %{
        "elixir_1.15" => ["libgraph_0.16", "jason_1.4"],
        "elixir_1.16" => ["libgraph_0.16", "jason_1.4"]
      },
      # SHA-256 of the current dependency definition
      checksum: "7a22ba2eaae8411e497891a90f4f511b1301786d34a6dcde5a347adc01d68517"
    }
  end

  @doc """
  Verifies the runtime environment against the manifest.
  Raises if dependency discrepancies or tampering are detected.
  """
  @spec validate_environment!() :: :ok
  def validate_environment! do
    spec = get_spec()

    # 1. Integrity Check
    unless verify_checksum(spec) do
      raise "Security Violation: Dependency manifest checksum mismatch."
    end

    # 2. Runtime Dependency Check
    Enum.each(spec.dependencies, fn {dep, _version} ->
      unless Code.ensure_loaded?(dep) do
        raise "Environment Mismatch: Required dependency '#{dep}' not loaded."
      end
    end)

    :telemetry.execute([:procoder, :planner, :dependencies, :validated], %{})
    :ok
  end

  @doc """
  Health check callback for the supervisor tree.
  """
  @spec health_check() :: :ok | {:error, term()}
  def health_check do
    try do
      validate_environment!()
    rescue
      e -> {:error, e.message}
    end
  end

  defp verify_checksum(spec) do
    # Internal validation of the manifest integrity
    calculated = :crypto.hash(:sha256, :erlang.term_to_binary(Map.delete(spec, :checksum)))
                 |> Base.encode16(case: :lower)

    calculated == spec.checksum
  end
end

defmodule ProCoder.Planner.LogicEngine.DAGOrchestrator.Types do
  @moduledoc """
  Foundational data structures for the ProCoder Planner's DAG orchestration engine.

  This module defines the structural representation of task nodes and the global 
  graph state, providing the contract for state management, dependency tracking, 
  and self-healing recovery subgraphs.
  """

  @derive {Jason.Encoder, only: [:id, :task_type, :payload, :status, :retry_count, :recovery_node_id, :metadata]}
  defstruct id: nil,
            task_type: nil,
            payload: %{},
            status: :pending,
            retry_count: 0,
            recovery_node_id: nil,
            metadata: %{
              created_at: nil,
              transitioned_at: nil,
              duration_ms: 0,
              integrity_hash: nil
            }

  @type status :: :pending | :running | :completed | :failed
  @type task_node :: %__MODULE__{
          id: String.t() | nil,
          task_type: atom() | nil,
          payload: map(),
          status: status(),
          retry_count: non_neg_integer(),
          recovery_node_id: String.t() | nil,
          metadata: map()
        }

  @doc """
  Validates input map against the TaskNode structure requirements.
  """
  @spec from_map(map()) :: {:ok, task_node()} | {:error, term()}
  def from_map(attrs) do
    # Ensure mandatory fields are present
    case Map.take(attrs, [:id, :task_type]) do
      %{id: _, task_type: _} ->
        node = struct(__MODULE__, attrs)
        {:ok, node}
      _ ->
        {:error, :missing_required_fields}
    end
  end

  defimpl String.Chars do
    def to_string(%ProCoder.Planner.LogicEngine.DAGOrchestrator.Types{id: id, task_type: type, status: status}),
      do: "TaskNode(id=#{id}, type=#{type}, status=#{status})"
  end

  # GraphState Structure
  defmodule GraphState do
    @moduledoc "Container for the Planner's current DAG execution state."
    @derive {Jason.Encoder, only: [:session_id, :graph, :node_registry, :history_stack]}
    defstruct session_id: nil,
              graph: nil,
              node_registry: %{},
              history_stack: []
  end

  @type graph_state :: %GraphState{
          session_id: String.t() | nil,
          graph: Graph.t() | nil,
          node_registry: map(),
          history_stack: list(term())
        }

  @doc """
  Creates a new GraphState container.
  """
  @spec new_state(String.t()) :: graph_state()
  def new_state(session_id) do
    %GraphState{
      session_id: session_id,
      graph: Graph.new(type: :directed),
      node_registry: %{},
      history_stack: []
    }
  end

  defimpl String.Chars, for: GraphState do
    def to_string(%{session_id: sid}), do: "GraphState(session=#{sid})"
  end
end
